                    isExpanded={isExpanded}
                    onClick={() => setIsExpanded(!isExpanded)}
                />
            </DeviceTile>
            { isExpanded && <DeviceDetails device={device} /> }
            <br />
            <DeviceVerificationStatusCard device={device} />
        </>
        }
    </SettingsSubsection>;
};

